// lib/services/svg_palette_data.dart
//
// All 188 twenty-colour palettes (ported from PaletteData.swift). Each is split into four
// 5-colour palettes: "<Name> 1" = colours 1-5, "<Name> 2" = 6-10, "<Name> 3" = 11-15,
// "<Name> 4" = 16-20.

class SvgColorPalette {
  final String name;
  final List<String> colors;
  const SvgColorPalette(this.name, this.colors);
}

List<SvgColorPalette> expandedPalettes() {
  final out = <SvgColorPalette>[];
  for (final (name, colors) in palettes20) {
    if (colors.length != 20) continue;
    final c = colors.map((e) => e.toLowerCase()).toList();
    for (var part = 0; part < 4; part++) {
      out.add(SvgColorPalette('$name ${part + 1}', c.sublist(part * 5, part * 5 + 5)));
    }
  }
  return out;
}

